use std::sync::{Arc, Weak};

struct Node { parent: Weak<Node>, children: Vec<Arc<Node>> }

let child = Arc::new(Node { parent: Arc::downgrade(&parent), children: vec![] });
if let Some(p) = child.parent.upgrade() {   // None once the parent is dropped
    p.report();                            // strong for the duration of the use
}
